                                  "text.startswith(prefix + '/')\n"
                                  "                    for prefix in ('Questify.xcodeproj/xcuserdata',\n"
                                  '                                   '
                                  "'Questify.xcodeproj/project.xcworkspace/xcuserdata')))\n"
                                  '    def failed(error):\n'
                                  "        raise ValueError('Unreadable finite club historical context') "
                                  'from error\n'
                                  '    for directory, subdirectories, files in _club_os.walk(root, '
                                  'onerror=failed):\n'
                                  '        ignored = {name for name in subdirectories + files\n'
                                  '                   if generated((Path(directory) / '
                                  'name).relative_to(root))}\n'
                                  '        for name in subdirectories + files:\n'
                                  '            if name not in ignored and (Path(directory) / '
                                  'name).is_symlink():\n'
                                  "                raise ValueError('Symlink in finite club historical "
                                  "context')\n"
                                  '        subdirectories[:] = [name for name in subdirectories if name not '
                                  'in ignored]\n'
                                  '        for name in files:\n'
                                  '            if name not in ignored:\n'
                                  '                path = Path(directory) / name\n'
                                  '                result[path.relative_to(root).as_posix()] = '
                                  'digest(path.read_bytes())\n'
                                  '    return result\n'
                                  '\n'
                                  '\n'
                                  '\n'
                                  '# Only the finite complete-source/AST-pinned pure declarations below '
